const u = new URL("https://example.com:8080/a/b?x=1&y=hello%20world#frag")
console.log(u.hostname)  // example.com
console.log(new URL("/p", "http://h.com/a").href)  // http://h.com/p

const pattern = new URLPattern({ pathname: "/books/:id" })
console.log(pattern.test("https://example.com/books/123"))  // true
const m = pattern.exec("https://example.com/books/123")
if (m !== null) { console.log(m.pathname.groups.id) }  // 123

import { parse, format } from 'url'
const u = parse('https://a.com/x?q=1')
console.log(format(u)) // https://a.com/x?q=1

import { urlToHttpOptions } from 'url'
const o = urlToHttpOptions(new URL('https://h:8443/p?a=1'))
console.log(o.path) // /p?a=1
